// The bash integration: the script generated by the init subcommand.
package shell

import (
	"errors"
	"fmt"
	"strings"
)

// BashInit returns the bash integration script, the output of `<prog> init
// bash`: a script meant to be evaluated by an interactive bash,
//
//	eval "$(wtr init bash --key ctrl-o)"
//
// which binds key to a readline command opening the inline picker of bin right
// below the prompt. The widget implements the flow described in Run: it
// captures stdout, the picker renders on the terminal and reports its result
// as a mode line ("run" or "insert") followed by the command line, and the
// widget then runs it (enter) or inserts it in the prompt (tab).
//
// readline offers no way to submit a line (accept-line) from shell code, but a
// key can expand to a macro ending in a key bound to accept-line: the script
// binds key to two invisible sequences, the first dispatching the widget and
// the second — the tail — re-bound by the widget to accept-line when the
// chosen command must run and to nothing otherwise (the route atuin's bash
// widget takes too). The command is then submitted by readline itself, so it
// runs exactly like a typed line: prompt, history, exit status and all. The
// chain needs bash 4.3 or later (in bash <= 4.2 bind -x takes only two-byte
// sequences).
//
// prog is the name the binary was invoked as; it appears in the script's
// comments. bin is the command the widget launches — the invoked name,
// resolved through PATH at press time, or an absolute path. key is a combo
// name ("ctrl-o", "alt-x") or a raw readline key sequence as bind takes it
// ("\e[15~" for F5).
func BashInit(prog, bin, key string) (string, error) {
	if bin == "" {
		return "", errors.New("empty binary path")
	}
	if prog == "" {
		prog = "wtr"
	}
	seq, name, err := parseBashBindKey(key)
	if err != nil {
		return "", err
	}

	var b strings.Builder
	fmt.Fprintf(&b, `# %s: bash integration, %s opens the inline picker.
#
# Evaluate it in an interactive shell (bash 4.3 or later):
#
#   eval "$(%s init bash --key %s)"
#
# WTR_BIN overrides the binary the widget launches, WTR_FLAGS passes it extra
# flags, e.g. WTR_FLAGS=--debug-area to see the border of the managed area.

WTR_BIN="${WTR_BIN:-%s}"
WTR_FLAGS="${WTR_FLAGS:-}"
`, prog, name, prog, name, bin)

	// Flow control keys (Ctrl-S is XOFF, Ctrl-Q is XON) are eaten by the
	// terminal before readline sees them: turn IXON off for the session.
	ixon := ""
	if disablesBashIXON(seq) {
		ixon = `
  # The terminal reads the bound key as flow control (Ctrl-S is XOFF, Ctrl-Q
  # is XON) and would swallow it instead of delivering it to readline. Turn
  # IXON off for this session; 'stty ixon' restores the default.
  stty -ixon 2>/dev/null
`
	}

	fmt.Fprintf(&b, `
# The widget bound to the key: the picker reads the terminal through /dev/tty
# (like the zsh widget does, rather than trust where stdin points) and renders
# there, since stdout is captured to receive its result here — a mode line
# ("run" or "insert") followed by the command line.
_wtr_widget() {
  local out
  # (${flags[@]+...} keeps an empty list safe under set -u on older bash.)
  local -a flags=() lines
  if [[ -n $WTR_FLAGS ]]; then read -r -a flags <<< "$WTR_FLAGS"; fi
  # --shell posix: bash reads the line the widget inserts, and it comes
  # before WTR_FLAGS so a user can override it.
  out=$("$WTR_BIN" --inline --shell posix ${flags[@]+"${flags[@]}"} < /dev/tty)

  local mode=""
  mapfile -t lines <<< "$out"
  if (( ${#lines[@]} >= 2 )); then mode=${lines[0]}; fi
  local tail=""
  case $mode in
    run)
      # Hand the command line to readline and let it submit it: the command
      # runs like a typed line, land in the history and leave its exit status
      # to the next prompt.
      READLINE_LINE=${lines[1]}
      READLINE_POINT=${#READLINE_LINE}
      tail=accept-line
      ;;
    insert)
      # Put the command at the cursor; the line stays in the prompt, to edit
      # or run by hand.
      READLINE_LINE="${READLINE_LINE:0:READLINE_POINT}${lines[1]}${READLINE_LINE:READLINE_POINT}"
      READLINE_POINT=$((READLINE_POINT + ${#lines[1]}))
      ;;
  esac
  _wtr_tail "$tail"
}

# _wtr_tail binds the tail of the key's macro: accept-line submits the line
# after the widget returns, "" leaves it alone.
_wtr_tail() {
  local action=$1 keymap
  for keymap in emacs-standard vi-insert vi-command; do
    if [[ -n $action ]]; then
      bind -m "$keymap" "\"$WTR_TAIL\": $action"
    else
      bind -m "$keymap" "\"$WTR_TAIL\": \"\""
    fi
  done
}

# Bind the key where there is a line editor to bind it to, and a line buffer
# to hand the result back through: both need an interactive shell, and the
# chain below needs bash 4.3 or later.
if [[ $- == *i* ]] && ((BASH_VERSINFO[0] > 4 || BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] >= 3)); then

  # Pressing the key expands to two invisible sequences: the first opens the
  # picker, the second is the tail above. readline has no way to submit a line
  # from shell code; a macro ending in accept-line is how the widget gets a
  # chosen command submitted.
  WTR_KEY='%s'
  WTR_RUN='\C-x\C-_w1\a'
  WTR_TAIL='\C-x\C-_w2\a'
%s
  for _wtr_keymap in emacs-standard vi-insert vi-command; do
    bind -m "$_wtr_keymap" "\"$WTR_KEY\": \"$WTR_RUN$WTR_TAIL\""
    bind -m "$_wtr_keymap" -x "\"$WTR_RUN\": _wtr_widget"
    bind -m "$_wtr_keymap" "\"$WTR_TAIL\": \"\""
  done
  unset -v WTR_KEY WTR_RUN _wtr_keymap
elif [[ $- == *i* ]]; then
  echo "%s: the bash widget needs bash 4.3 or later" >&2
fi
`, seq, ixon, prog)

	return b.String(), nil
}

// parseBashBindKey turns a --key value into the sequence bind expects and a
// human-readable name for the script's header comment: "ctrl-o" and "alt-x"
// are translated ("\C-o", "\ex"); anything starting with a backslash is a raw
// readline key sequence and is passed through ("\e[15~" for F5).
func parseBashBindKey(spec string) (seq, name string, err error) {
	key := strings.TrimSpace(spec)
	if key == "" {
		return "", "", errors.New("empty key: use a combo name like ctrl-o or a raw sequence like \\e[15~")
	}
	if strings.HasPrefix(key, `\`) {
		if len(key) < 2 {
			return "", "", fmt.Errorf("invalid key %q: a backslash must introduce a key sequence", spec)
		}
		return key, key, nil
	}
	if rest, ok := cutPrefixFold(key, "ctrl-"); ok {
		if len(rest) != 1 || !isASCIILetter(rest[0]) {
			return "", "", fmt.Errorf("invalid key %q: ctrl- takes one letter, e.g. ctrl-o", spec)
		}
		return `\C-` + strings.ToLower(rest), "Ctrl-" + strings.ToUpper(rest), nil
	}
	if rest, ok := cutPrefixFold(key, "alt-"); ok {
		if len(rest) != 1 || rest[0] < 0x21 || rest[0] > 0x7e {
			return "", "", fmt.Errorf("invalid key %q: alt- takes one printable character, e.g. alt-x", spec)
		}
		return `\e` + rest, "Alt-" + rest, nil
	}
	return "", "", fmt.Errorf("invalid key %q: use a combo name like ctrl-o or alt-x, or a raw sequence like \\e[15~", spec)
}

// disablesBashIXON reports whether binding seq needs IXON turned off: Ctrl-S
// is XOFF and Ctrl-Q is XON, so the terminal would swallow the key instead of
// delivering it to readline (bind writes them "\C-s" and "\C-q").
func disablesBashIXON(seq string) bool {
	return strings.EqualFold(seq, `\C-s`) || strings.EqualFold(seq, `\C-q`)
}
